import{b as o,O as r,g as e,j as a}from"./chunks/framework.DcaUmd3X.js";const g=JSON.parse('{"title":"敏捷测试（下）—— 落地与实践","description":"","frontmatter":{},"headers":[],"relativePath":"testing/engineering/agile-testing-2/index.md","filePath":"测试理论与实践/4.现代测试工程/12.敏捷测试（下）.md","lastUpdated":1781625968000}'),d={name:"testing/engineering/agile-testing-2/index.md"};function l(i,t,n,s,h,u){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="敏捷测试-下-——-落地与实践" tabindex="-1">敏捷测试（下）—— 落地与实践 <a class="header-anchor" href="#敏捷测试-下-——-落地与实践" aria-label="Permalink to &quot;敏捷测试（下）—— 落地与实践&quot;">​</a></h1><blockquote><p>上一章把四象限和原则讲清楚了。这一章把它落地——每个象限具体用什么工具、谁来负责、怎么在迭代中排期，以及需求变更时怎么应对。</p></blockquote><h2 id="四象限的工具链实战" tabindex="-1">四象限的工具链实战 <a class="header-anchor" href="#四象限的工具链实战" aria-label="Permalink to &quot;四象限的工具链实战&quot;">​</a></h2><p>每个象限背后都有具体的工具和方法论。以下不是&quot;必须用这个&quot;的推荐清单，而是&quot;业界常用、经过了大量团队验证&quot;的参考。</p><h3 id="q1-工具链-技术基础盘" tabindex="-1">Q1 工具链：技术基础盘 <a class="header-anchor" href="#q1-工具链-技术基础盘" aria-label="Permalink to &quot;Q1 工具链：技术基础盘&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具/方法</th><th>做什么</th><th>为什么是它</th></tr></thead><tbody><tr><td><strong>JUnit / TestNG / pytest</strong></td><td>单元测试框架</td><td>各自语言生态的事实标准，CI 集成成熟</td></tr><tr><td><strong>Mockito / Moq / unittest.mock</strong></td><td>Mock 框架</td><td>隔离外部依赖，让单元测试快且稳定</td></tr><tr><td><strong>JaCoCo / Istanbul / coverage.py</strong></td><td>代码覆盖率</td><td>不是追求数字，而是帮你发现&quot;哪块代码从来没被测过&quot;</td></tr><tr><td><strong>SonarQube</strong></td><td>静态代码分析</td><td>在 CI 中自动扫描代码异味、潜在 bug、安全漏洞</td></tr></tbody></table><p>Q1 的实践要点：</p><ul><li>每次提交自动触发，结果要在 5 分钟内出来（<a href="/testing/execution/regression-release.html">回归测试与上线标准</a>的时间预算）</li><li>覆盖率不是 KPI——80% 的分支覆盖比 95% 的语句覆盖更有意义</li><li>Mock 要适度——Mock 了整个世界的单元测试，测的是 Mock 而不是真实行为</li></ul><h3 id="q2-工具链-业务验收" tabindex="-1">Q2 工具链：业务验收 <a class="header-anchor" href="#q2-工具链-业务验收" aria-label="Permalink to &quot;Q2 工具链：业务验收&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具/方法</th><th>做什么</th><th>为什么是它</th></tr></thead><tbody><tr><td><strong>Cucumber / SpecFlow / Behave</strong></td><td>BDD 框架</td><td>用 Given-When-Then 写验收场景，业务方也能看懂</td></tr><tr><td><strong>FitNesse</strong></td><td>表格化验收测试</td><td>用 wiki 风格的表格定义输入输出，适合数据驱动的场景</td></tr><tr><td><strong>Robot Framework</strong></td><td>关键字驱动测试</td><td>用自然语言关键字编写测试，适合非开发人员上手</td></tr><tr><td><strong>Selenium / Playwright</strong></td><td>Web 端到端自动化</td><td>把验收场景自动化，作为回归套件的一部分</td></tr></tbody></table><p>Q2 的实践要点：</p><ul><li>验收测试要在编码之前写——或者在编码的同时写——而不是&quot;做完再补&quot;</li><li>Given-When-Then 的场景不要写得太细——&quot;用户登录&quot;是一个步骤，不需要写&quot;用户输入账号、输入密码、点击按钮&quot;</li><li>验收测试的数量要精不要多——核心业务流程每人 3~5 条就够，太多了维护成本爆炸</li></ul><h3 id="q3-工具链-业务探索" tabindex="-1">Q3 工具链：业务探索 <a class="header-anchor" href="#q3-工具链-业务探索" aria-label="Permalink to &quot;Q3 工具链：业务探索&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具/方法</th><th>做什么</th><th>为什么是它</th></tr></thead><tbody><tr><td><strong>思维导图（XMind / Miro）</strong></td><td>画出探索方向</td><td>用可视化方式梳理测试点和它们之间的关系</td></tr><tr><td><strong>录屏工具（OBS / Loom）</strong></td><td>记录操作和现象</td><td>比写 Bug 描述更快更直观，特别是 UI 动效问题</td></tr><tr><td><strong>浏览器 DevTools</strong></td><td>观察网络、控制台、性能</td><td><a href="/testing/methodology/exploratory-testing-2.html">探索式测试（下）</a>的观察技能在 Web 场景下的落地工具</td></tr><tr><td><strong>Charles / Fiddler</strong></td><td>HTTP 代理抓包</td><td>修改请求/响应，模拟各种网络条件和数据场景</td></tr></tbody></table><p>Q3 的实践要点：</p><ul><li>Q3 不等于&quot;随便测&quot;。每次探索都要有章程，有会话输出</li><li>不要等着&quot;全部开发完&quot;再做 Q3——功能一出来就做第一轮快速探索，发现问题立刻反馈</li><li>探索中发现的高价值场景应该反向沉淀到 Q1/Q2 的自动化用例中</li></ul><h3 id="q4-工具链-技术质量保障" tabindex="-1">Q4 工具链：技术质量保障 <a class="header-anchor" href="#q4-工具链-技术质量保障" aria-label="Permalink to &quot;Q4 工具链：技术质量保障&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具/方法</th><th>做什么</th><th>为什么是它</th></tr></thead><tbody><tr><td><strong>JMeter / k6 / Locust</strong></td><td>性能/压力测试</td><td>脚本化压测，可在 CI 中定时跑（详见<a href="/testing/execution/test-process.html">测试全流程</a>）</td></tr><tr><td><strong>OWASP ZAP / Burp Suite</strong></td><td>安全扫描与渗透</td><td><a href="/testing/methodology/security-testing.html">安全测试与渗透测试</a>已展开</td></tr><tr><td><strong>Lighthouse / WebPageTest</strong></td><td>Web 性能与体验</td><td>前端性能指标的自动化评估</td></tr><tr><td><strong>BrowserStack / Sauce Labs</strong></td><td>跨浏览器/设备兼容性</td><td>在云端真实设备上跑测试，不用自己维护设备农场</td></tr></tbody></table><p>Q4 的实践要点：</p><ul><li>Q4 不需要每个迭代都全做——按风险排期，安全每个迭代做轻量扫描，性能在发布前和大改动时做</li><li>和 Q1 一样，尽量自动化并集成到管道——&quot;还记得上线前要跑一遍安全扫描&quot;不如&quot;每次提交自动跑一遍&quot;</li><li>Q4 的门槛在工具配置和知识储备——团队里至少要有一个人能驾驭性能和安全工具</li></ul><h3 id="不是所有测试都值得自动化" tabindex="-1">不是所有测试都值得自动化 <a class="header-anchor" href="#不是所有测试都值得自动化" aria-label="Permalink to &quot;不是所有测试都值得自动化&quot;">​</a></h3><p>四个象限的工具链铺开来用，团队很容易陷入&quot;自动化一切&quot;的冲动。但自动化的投入产出比不是均匀的——有些测试自动化一本万利，有些则得不偿失。</p><p>《敏捷测试》给了一个实用的优先级公式：</p><blockquote><p><strong>优先自动化的测试 = 运行频率高 × 失败可能性大 × 失败后果严重</strong></p></blockquote><p>按这三个维度，测试可以分为四个梯队：</p><table tabindex="0"><thead><tr><th>梯队</th><th>特征</th><th>举例</th><th>策略</th></tr></thead><tbody><tr><td><strong>第一梯队</strong></td><td>高频 + 高失败率 + 高影响</td><td>登录、支付、核心业务流程</td><td>必须自动化，每次提交都跑</td></tr><tr><td><strong>第二梯队</strong></td><td>中频 + 中影响</td><td>搜索、列表筛选、表单提交</td><td>应该自动化，每日构建跑</td></tr><tr><td><strong>第三梯队</strong></td><td>低频 + 低影响</td><td>后台管理、报表导出、配置页面</td><td>有资源就自动化，没资源手工回归</td></tr><tr><td><strong>第四梯队</strong></td><td>极低频 + 极低影响</td><td>帮助页面文案、静态协议页</td><td>手工看一次就够了</td></tr></tbody></table><p>注意，不是&quot;Q1 全部自动化、Q3 全部手工&quot;。有些 Q1 层面的测试（比如一个废弃模块的单元测试）不值得维护；有些 Q3 层面的测试（比如回归时每次都走一遍的用户核心路径）值得固化为自动化脚本。<strong>象限决定测试的目的，频率和风险决定自动化的优先级。</strong></p><h2 id="需求变更-敏捷测试中的常态应对" tabindex="-1">需求变更：敏捷测试中的常态应对 <a class="header-anchor" href="#需求变更-敏捷测试中的常态应对" aria-label="Permalink to &quot;需求变更：敏捷测试中的常态应对&quot;">​</a></h2><p>敏捷宣言说&quot;拥抱变化&quot;，但在测试场景中，需求变更意味着你刚写完的用例可能要改、刚搭好的测试数据可能失效、刚跑通的自动化可能挂掉。抱怨没用，下面是怎么应对。</p><h3 id="变更到来时先问三个问题" tabindex="-1">变更到来时先问三个问题 <a class="header-anchor" href="#变更到来时先问三个问题" aria-label="Permalink to &quot;变更到来时先问三个问题&quot;">​</a></h3><p>不是所有需求变更都同等影响测试。收到变更后先快速判断：</p><ol><li><strong>影响范围</strong>：改了哪个模块？这个模块关联了哪些其他功能？——这一步决定选择性回归的用例范围</li><li><strong>影响程度</strong>：是界面文案微调，还是支付逻辑重构？——决定回归深度</li><li><strong>时间余量</strong>：离迭代结束还有几天？——决定你能做多深的重新测试</li></ol><h3 id="用活文档对抗变更" tabindex="-1">用活文档对抗变更 <a class="header-anchor" href="#用活文档对抗变更" aria-label="Permalink to &quot;用活文档对抗变更&quot;">​</a></h3><p>如果测试用例是一份上百页的 Word 文档，每次需求变更都要翻文档找哪些用例需要改——维护成本就是噩梦。</p><p>敏捷测试的解法是<strong>用可执行的验收测试（Q2）作为&quot;活文档&quot;</strong>。验收测试本身就是可运行的，需求变了你改对应的 scenario，跑一遍就看得出哪些场景受影响。比&quot;文档说测完了但实际跟代码对不上&quot;可靠得多。</p><h3 id="测试用例的及时更新" tabindex="-1">测试用例的及时更新 <a class="header-anchor" href="#测试用例的及时更新" aria-label="Permalink to &quot;测试用例的及时更新&quot;">​</a></h3><p>需求变更后，测试用例的更新不是&quot;有空再改&quot;：</p><ul><li>立刻标记受影响的用例为&quot;待更新&quot;，不要让它混在&quot;仍有效&quot;的用例里</li><li>和开发确认变更细节后再更新——别对着旧信息自己闷头改</li><li>更新完用例后跑一轮受影响区域的回归，确认变更没有连带破坏</li></ul><h3 id="时间被压缩时的取舍" tabindex="-1">时间被压缩时的取舍 <a class="header-anchor" href="#时间被压缩时的取舍" aria-label="Permalink to &quot;时间被压缩时的取舍&quot;">​</a></h3><p>敏捷迭代最常见的问题：开发延期，测试时间被压到最后两三天。这时候不是抱怨，而是做<strong>风险驱动的取舍</strong>：</p><ol><li>先确保 Q1 自动化全部通过——底层没崩</li><li>再跑本次改动相关的核心验收测试（Q2）</li><li>用一次限时探索会话（Q3，60 分钟）快速摸一遍高风险点</li><li>Q4 的非功能测试标为风险已知，放到下个迭代优先级里</li></ol><blockquote><p>这不是&quot;降低标准&quot;，而是&quot;管理风险&quot;。你坦率地说&quot;因为时间限制，本次 Q4 未覆盖，残留风险是 xxx&quot;，比假装什么都测完了要专业得多。</p></blockquote><h2 id="跨角色协作-测试不是孤岛" tabindex="-1">跨角色协作：测试不是孤岛 <a class="header-anchor" href="#跨角色协作-测试不是孤岛" aria-label="Permalink to &quot;跨角色协作：测试不是孤岛&quot;">​</a></h2><p>敏捷测试的落地最卡的地方往往不是工具和技术，而是<strong>人和人之间的协作方式</strong>。</p><h3 id="测试和开发的协作" tabindex="-1">测试和开发的协作 <a class="header-anchor" href="#测试和开发的协作" aria-label="Permalink to &quot;测试和开发的协作&quot;">​</a></h3><ul><li><strong>不等提测</strong>：写了一个接口就找测试来快速看一眼，发现方向偏差马上调整。不要攒到&quot;全部做完&quot;才交给测试</li><li><strong>一起写验收标准</strong>：不是开发写完代码、测试对着需求文档猜怎么测。迭代前两三天，开发和测试坐在一起，把验收场景过一遍</li><li><strong>Bug 不仇恨</strong>：Bug 是信息，不是责任。<a href="/testing/execution/bug-management.html">缺陷管理</a>讲的 Bug Council 就是协作处理 Bug 的标准方式</li></ul><h3 id="测试和产品的协作" tabindex="-1">测试和产品的协作 <a class="header-anchor" href="#测试和产品的协作" aria-label="Permalink to &quot;测试和产品的协作&quot;">​</a></h3><ul><li><strong>追问模糊需求</strong>：测试人员应该是团队里对需求追问最多的人。&quot;用户应该能够找到想要的东西&quot;——什么叫&quot;找到&quot;？搜索？推荐？分类浏览？</li><li><strong>用实例澄清</strong>：当产品说&quot;这个按钮应该在合适的时候出现&quot;——你当场构造三个具体场景：&quot;用户余额不足时算不算合适的时候？用户是 VIP 时算不算？&quot;</li><li><strong>Demo 不只是展示</strong>：迭代结束的 Demo 不是&quot;演示新功能&quot;，而是一次非正式的验收测试。让产品在 Demo 上亲自操作，你观察——他的困惑就是你的 bug</li></ul><h3 id="测试和测试的协作" tabindex="-1">测试和测试的协作 <a class="header-anchor" href="#测试和测试的协作" aria-label="Permalink to &quot;测试和测试的协作&quot;">​</a></h3><p>如果团队里不止一个测试人员：</p><ul><li><strong>交叉探索</strong>：A 测过的模块让 B 花 20 分钟快速摸一遍——B 的盲区和 A 不一样</li><li><strong>同行评审测试用例</strong>：和代码走查一样，测试用例也值得被 review。&quot;你这个等价类划分漏了空字符串的情况&quot;</li></ul><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>四象限各有对应工具链——不需要全用，但要了解每象限的&quot;配置&quot;应该长什么样</li><li>不是所有测试都值得自动化——优先级 = 高频 × 高失败率 × 高后果。象限决定测试目的，频率和风险决定自动化优先级</li><li>Q1 自动化 + Q2 验收 &quot;活文档&quot; + Q3 探索式 + Q4 按风险排期——四个象限搭配构成迭代级的质量保障体系</li><li>需求变更时先判断影响范围→程度→时间余量，用例立刻标记待更新并和开发确认后再改</li><li>时间被压缩时做风险驱动的取舍——不是降标准，而是管理风险、坦率声明残留风险</li><li>跨角色协作的关键词是&quot;不等&quot;——不等提测、不等写完、不等 Demo，持续沟通贯穿整个迭代</li></ol>',53)])])}const b=o(d,[["render",l]]);export{g as __pageData,b as default};
